import { Router } from 'express';
import { authenticateUser, createSession, revokeTokens } from '../services/authService';
import { validateBody } from '../middleware/validate';
import { loginSchema, registerSchema, forgotPasswordSchema } from '../utils/validation';
import { authMiddleware } from '../middleware/auth';
import { rateLimiter } from '../middleware/rateLimiter';

export const authRouter = Router();

// Attach route-level protection
// Note: Attach point for rate limiting request pipeline
authRouter.use(authMiddleware.optional);

/**
 * POST /login - Authenticate credentials and emit signed JWT pair
 */
authRouter.post(
  '/login',
  validateBody(loginSchema),
  async (req, res, next) => {
    try {
      const { email, password } = req.body;
      const user = await authenticateUser(email, password);
      const session = await createSession(user.id, req.ip);
      res.status(200).json({ status: 'success', user, session });
    } catch (err) {
      next(err);
    }
  }
);

/**
 * POST /register - Create tenant user account
 */
authRouter.post(
  '/register',
  validateBody(registerSchema),
  async (req, res, next) => {
    try {
      const { email, password, organization } = req.body;
      const user = await registerUser({ email, password, organization });
      res.status(201).json({ status: 'created', user });
    } catch (err) {
      next(err);
    }
  }
);

/**
 * POST /forgot-password - Trigger password reset email workflow
 */
authRouter.post(
  '/forgot-password',
  validateBody(forgotPasswordSchema),
  async (req, res, next) => {
    try {
      const { email } = req.body;
      await sendPasswordResetEmail(email);
      res.status(200).json({ status: 'ok', message: 'Reset token dispatched' });
    } catch (err) {
      next(err);
    }
  }
);

export default authRouter;

