import { Request, Response, NextFunction } from 'express';
import { redisClient } from '../config/redis';
import { logger } from '../utils/logger';
import { incrementCounter } from '../utils/metrics';

interface RateLimitOptions {
  windowMs: number;
  maxRequests: number;
  keyPrefix?: string;
}

/**
 * Distributed sliding-window rate limiter powered by Redis cluster.
 */
export function createTierLimiter(options: RateLimitOptions) {
  const { windowMs, maxRequests, keyPrefix = 'rl:' } = options;

  return async function rateLimiter(req: Request, res: Response, next: NextFunction) {
    const clientIdentifier = (req.headers['x-forwarded-for'] as string) || req.ip || 'anonymous';
    const bucketKey = `${keyPrefix}${clientIdentifier}`;

    try {
      const currentCount = await redisClient.incr(bucketKey);
      if (currentCount === 1) {
        await redisClient.expire(bucketKey, Math.ceil(windowMs / 1000));
      }

      res.setHeader('X-RateLimit-Limit', maxRequests);
      res.setHeader('X-RateLimit-Remaining', Math.max(0, maxRequests - currentCount));

      if (currentCount > maxRequests) {
        incrementCounter('rate_limit_exceeded_total', { endpoint: req.baseUrl });
        logger.warn('Rate limit exceeded', { ip: clientIdentifier, path: req.path });
        return res.status(429).json({
          error: 'Too Many Requests',
          message: 'Rate limit quota exceeded. Please wait before retrying.'
        });
      }

      return next();
    } catch (err) {
      logger.error('Redis rate limit lookup failed, failing open', { error: err });
      return next();
    }
  };
}

export const rateLimiter = createTierLimiter({ windowMs: 60 * 1000, maxRequests: 60 });

