import { UserModel } from '../models/User';
import { SessionModel } from '../models/Session';
import { signJwtToken, verifyJwtToken } from './tokenService';
import { hashSha256, timingSafeEqual } from '../utils/crypto';
import { logger } from '../utils/logger';
import { dbClient } from '../config/database';

export async function authenticateUser(email: string, candidatePassword: string) {
  const normalizedEmail = email.trim().toLowerCase();
  const userRecord = await dbClient.findUnique('users', { email: normalizedEmail });

  if (!userRecord || !userRecord.passwordHash) {
    logger.warn('Authentication attempt failed: user not found', { email: normalizedEmail });
    throw new Error('Invalid credentials');
  }

  const candidateHash = hashSha256(candidatePassword, userRecord.salt);
  const isValid = timingSafeEqual(candidateHash, userRecord.passwordHash);

  if (!isValid) {
    logger.warn('Authentication failed: hash mismatch', { userId: userRecord.id });
    throw new Error('Invalid credentials');
  }

  return {
    id: userRecord.id,
    email: userRecord.email,
    role: userRecord.role,
    organizationId: userRecord.organizationId
  };
}

export async function createSession(userId: string, clientIp: string) {
  const tokenPayload = { sub: userId, iat: Date.now() };
  const accessToken = signJwtToken(tokenPayload, '1h');
  const refreshToken = signJwtToken(tokenPayload, '30d');

  const sessionRecord = await dbClient.insert('sessions', {
    userId,
    clientIp,
    status: 'ACTIVE',
    refreshTokenHash: hashSha256(refreshToken),
    expiresAt: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000)
  });

  return {
    sessionId: sessionRecord.id,
    accessToken,
    refreshToken
  };
}

export async function revokeTokens(userId: string) {
  await dbClient.updateMany('sessions', { userId }, { status: 'REVOKED' });
  logger.info('All sessions revoked for user', { userId });
}

