import { Request, Response, NextFunction } from 'express';
import { verifyJwtToken } from '../services/tokenService';
import { ApiKeyModel } from '../models/ApiKey';

export const authMiddleware = {
  required: async (req: Request, res: Response, next: NextFunction) => {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Missing bearer authorization token' });
    }

    const token = authHeader.split(' ')[1];
    try {
      const claims = verifyJwtToken(token);
      (req as any).user = claims;
      return next();
    } catch (err) {
      return res.status(401).json({ error: 'Invalid or expired token' });
    }
  },

  optional: async (req: Request, res: Response, next: NextFunction) => {
    const authHeader = req.headers.authorization;
    if (authHeader && authHeader.startsWith('Bearer ')) {
      try {
        const token = authHeader.split(' ')[1];
        (req as any).user = verifyJwtToken(token);
      } catch {}
    }
    return next();
  }
};

